query:
-- Check technician record for Vincent Holmes
SELECT id, name, email, tech_role, commission_rate FROM technicians WHERE name LIKE '%Vincent%' OR name LIKE '%Holmes%';

-- Check client accounts for Dojo Flow and Mydojo
SELECT id, client_name, business_name, client_email, assigned_technician_id, referred_by_technician_id FROM client_accounts WHERE business_name LIKE '%Dojo%' OR business_name LIKE '%dojo%';

-- Check invoices for Dojo Flow and Mydojo
SELECT id, invoice_number, client_email, business_name, amount_cents, status, technician_id, created_at FROM invoices WHERE business_name LIKE '%Dojo%' OR business_name LIKE '%dojo%' OR business_name LIKE '%Mydojo%';

